fn queueIo(
    self: *Surface,
    msg: termio.Message,
    mutex: termio.Termio.MutexState,
) void {
    // In readonly mode, we don't allow any writes through to the pty.
    if (self.readonly) {
        switch (msg) {
            .write_small,
            .write_stable,
            .write_alloc,
            => {
                msg.deinit();
                return;
            },

            else => {},
        }
    }

    self.io.queueMessage(msg, mutex);
}

